//opening the .midi file and getting the whole content into a char array for later// analysis.// Mac version#include "stdio.h"#include "openmidfilemac.h"#include "muMIDIplayer.h"#include "muMenu.h"#include "muWindow.h"#include <Files.h>#include "muStates.h"#include "muEvents.h"#include "muGraphics.h"OSErr fOSErr;Handle gMidiBuf; // Handle to the raw midi buffer data read from a filestatic short gFileNum; //file number for opened .mid filestatic long gFileSize; //keeps track of how many bytes in the file//entry function for one stop shop in a midi player type environment//returns -1 for generic errors//returns -2 if the MTHd string can't be found inside the midi file //returns -3 for out of memory during handle allocation  int midiDialogLoadAndPrep(void){int openCode=0;  //MThd should be at position 0, but it might not, so we'll find it	openCode = openMIDIFile(); //will ask for a midi file and get its basic info//printf("openCode %d\n",openCode);if(openCode < 0) return openCode;//printf("stateBeforeLoad %d\n",gState.stateBeforeLoad);//routines from muMIDIPlayer.c		initSMF(); //default values for midi record				readSMFHeader(0); //get the actual values for midi recordallocateTracks(); //get the starters and parsers all readypreProcessEvents();primeMidiFaster(); //will HLock processedEventsreturn openCode;}//function that loads a known file directly in the same directory as the program//TODO//functions that loads an embedded DATA resource in the app directly//TODO//opens a MID, MIDI or Midi file through the std File dialog//returns -1 if there's an error. Inspect fOSErr with your own code if you wish//returns -3 for out of memory during handle allocationshort openMIDIFile(void)	{	ple oneShot;	plePtr myPP = &oneShot;	CInfoPBRec pb;	OSErr err;  	SFReply reply; /* used in file operations */  	SFTypeList myTypes; /* used in file operations */  	Point where = {50,50}; /* top left corner of Std file window */  	myTypes[0]='MIDI';   /* Those are the possible file type codes */  	myTypes[1]='MID ';   /* no idea if this one is used, but let's put it for good measure */  	myTypes[2]='Midi';   /* I've seen those too sometimes */      SFGetFile(where,"\pSelect a MIDI file",nil,3,myTypes,0L,&reply);	/*	SFPGetFile(where, "\pSelect a MIDI file", nil, 3, myTypes,		nil, &reply, nil, nil);  */  	if(!reply.good) return -1;		SetPort(muWinPtr);	{	EventRecord updateEv;		while(GetNextEvent(updateMask, &updateEv))		{		if(updateEv.what == updateEvt && (WindowPtr)updateEv.message == muWinPtr)			{			BeginUpdate(muWinPtr);			DrawAll();			EndUpdate(muWinPtr);			}		}	}	//printf("OpenMIDIFile %s %04x\n",reply.fName + 1, (unsigned short)reply.vRefNum);	pb.hFileInfo.ioNamePtr = reply.fName;	pb.hFileInfo.ioVRefNum = reply.vRefNum;	pb.hFileInfo.ioDirID = 0;	pb.hFileInfo.ioFDirIndex = 0;	err = PBGetCatInfoSync(&pb);	if(err != noErr)		{		//printf("PBGetCatInfoSync failed: %d\n", err);		return -1;		} //either there's a mistake in the file dialog fetching routine, or no file was selected		myPP = &gPlaylistFiles[gPlaylistCount];	myPP->vRefNum = reply.vRefNum;	myPP->dirID = pb.hFileInfo.ioFlParID;	myPP->fName[0] = reply.fName[0];	BlockMove(&reply.fName[1], &(myPP->fName[1]), reply.fName[0]);	myPP->good = true;				SetPort(muWinPtr);	return extractFileJuice(myPP);	}	short extractFileJuice(plePtr reply){//printf("%s %04x\n",reply->fName + 1, (unsigned short)reply->vRefNum);if(gState.stateBeforeLoad == STATE_PLAYING || gState.stateBeforeLoad == STATE_PAUSED)     		doneWithOnePlaying();fOSErr = HOpen(reply->vRefNum, reply->dirID, reply->fName, fsRdPerm, &gFileNum);//fOSErr = FSOpen(reply->fName,reply->vRefNum, &gFileNum);if(fOSErr != noErr) 	{	//printf("HOpen failed: %d\n", fOSErr);	return fOSErr;	}else     {    fOSErr = GetEOF(gFileNum, &gFileSize);    if(fOSErr != noErr) return -1;    else     	{    	if(gMidiBuf != NULL)     		{    		DisposHandle((Handle)gMidiBuf);    		gMidiBuf = NULL;    		}    	gMidiBuf = (char **) NewHandle(gFileSize);    	if(gMidiBuf == NULL)     	{    	FSClose(gFileNum);    	return -3; //out of memory    	}		    	HLock((Handle)gMidiBuf);    	fOSErr = FSRead(gFileNum, &gFileSize, *gMidiBuf);    	HUnlock((Handle)gMidiBuf);    			    	if(fOSErr != noErr)    		{    		DisposHandle(gMidiBuf);    		gMidiBuf = NULL;    		FSClose(gFileNum);    		return -1;    		}    	FSClose(gFileNum);    	//MemAlert();    	return 0; //the good scenario happens here    	}    }return 0;}void MemAlert(void){Str255 a,b;NumToString(FreeMem(),a);NumToString(MaxBlock(),b);                                                    ParamText("\pMaxBlock: ",b,"\p FreeMem: ",a);                                         Alert(150, NULL);                                              }	